@org.springframework.context.annotation.Import(V313TradeIntegrationTests.TimeConfig.class)
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
class V313TradeIntegrationTests {
 static final EmbeddedPostgres PG;
 static {try{PG=EmbeddedPostgres.builder().setPort(0).start();}catch(Exception e){throw new ExceptionInInitializerError(e);}}
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("spring.datasource.url",()->PG.getJdbcUrl("postgres","postgres"));r.add("spring.datasource.username",()->"postgres");r.add("spring.datasource.password",()->"postgres");r.add("pawday.auth.secret-key",()->"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=");for(String k:List.of("management.health.redis.enabled","management.health.rabbit.enabled","pawday.outbox.workers-enabled","pawday.outbox.consumer-enabled","pawday.search.enabled","pawday.storage.cleanup-enabled","pawday.checkout.expiry-enabled","pawday.ordering.expiry-enabled","pawday.payment.recovery-enabled","pawday.refund.recovery-enabled","pawday.settlement.worker-enabled"))r.add(k,()->false);r.add("pawday.booking.simulation-enabled",()->true);r.add("pawday.service-trade.simulation-enabled",()->true);}
 static class MutableClock extends Clock {
  volatile Instant current=Instant.now(); public Instant instant(){return current;}public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}
 }
 @org.springframework.boot.test.context.TestConfiguration static class TimeConfig {
  @org.springframework.context.annotation.Bean @org.springframework.context.annotation.Primary MutableClock tradeClock(){return new MutableClock();}
 }
 @Autowired MutableClock time;@Autowired cn.pawday.booking.ServiceTradeService tradeService;
 @Autowired JdbcTemplate db;@Autowired Crypto crypto;@Autowired Clock clock;@LocalServerPort int port;
 final JsonMapper json=JsonMapper.builder().build();final HttpClient http=HttpClient.newHttpClient();
 static final List<Map<String,Object>> SAMPLES=new CopyOnWriteArrayList<>();
 UUID store,merchantId,adminSession;String merchant,reader,user,other,foreign,admin;
 record Response(int status,JsonNode body){JsonNode data(){return body.get("data");}String id(){return data().get("id").asString();}}
 String key(){return UUID.randomUUID().toString();}
 String identity(boolean consumer,UUID m,UUID st,List<String> permissions){UUID p=UUID.randomUUID(),role=UUID.randomUUID();String realm=consumer?"CONSUMER":"MERCHANT";
  if(consumer){UUID u=UUID.randomUUID();db.update("INSERT INTO app_user(id,status) VALUES (?,'ACTIVE')",u);db.update("INSERT INTO identity_principal(id,realm,user_id) VALUES (?,'CONSUMER',?)",p,u);}else db.update("INSERT INTO identity_principal(id,realm,merchant_id,login_name,password_hash) VALUES (?,'MERCHANT',?,?,?)",p,m,key(),"TEST-ONLY");
  db.update("INSERT INTO role(id,scope_type,code,name) VALUES (?,?,?,'BOOKING TEST')",role,realm,key());for(String code:permissions)db.update("INSERT INTO role_permission SELECT ?,id FROM permission WHERE code=?",role,code);db.update("INSERT INTO principal_role VALUES (?,?,?)",p,role,realm);
  if(!consumer)db.update("INSERT INTO principal_store_scope VALUES (?,?,?)",p,m,st);
  String token=crypto.token();db.update("INSERT INTO auth_session(id,principal_id,access_token_hash,device_id,expires_at,refresh_expires_at,created_at) VALUES (?,?,?,'BOOKING-IT',?,?,?)",UUID.randomUUID(),p,crypto.hash(token),Timestamp.from(clock.instant().plusSeconds(86400)),Timestamp.from(clock.instant().plusSeconds(2592000)),Timestamp.from(clock.instant()));return token;
 }
 UUID store(UUID m){UUID s=UUID.randomUUID();db.update("INSERT INTO merchant_store(id,merchant_id,name) VALUES (?,?,'TEST booking store')",s,m);db.update("INSERT INTO nearby_store_profile(store_id,city,category,address,phone,business_hours,longitude,latitude,services,publication_status,claim_status) VALUES (?,'TEST','GROOMING','TEST address','123456','TEST hours',106,29,'[\"GROOMING\"]','PUBLISHED','VERIFIED')",s);return s;}
 @BeforeEach void setup(){time.current=Instant.now();merchantId=UUID.randomUUID();db.update("INSERT INTO merchant VALUES (?,'TEST booking merchant','ACTIVE')",merchantId);store=store(merchantId);merchant=identity(false,merchantId,store,List.of("store.read","store.nearby.write","service.terms.write","service.trade.read"));reader=identity(false,merchantId,store,List.of("store.read"));user=identity(true,null,null,List.of());other=identity(true,null,null,List.of());UUID m=UUID.randomUUID();db.update("INSERT INTO merchant VALUES (?,'TEST foreign','ACTIVE')",m);foreign=identity(false,m,store(m),List.of("store.read","store.nearby.write","service.terms.write","service.trade.read"));admin=admin();}
 Response req(String method,String path,Object body,String token,Map<String,String> headers){try{var builder=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1"+path)).timeout(Duration.ofSeconds(30));if(token!=null)builder.header("Authorization","Bearer "+token);headers.forEach(builder::header);builder.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body)));if(body!=null)builder.header("Content-Type","application/json");var response=http.send(builder.build(),HttpResponse.BodyHandlers.ofString());var result=json.readTree(response.body());SAMPLES.add(Map.of("method",method.toLowerCase(),"path",path,"status",response.statusCode(),"response",result));return new Response(response.statusCode(),result);}catch(Exception e){throw new AssertionError(e);}}
 Response get(String path,String token){return req("GET",path,null,token,Map.of());}
 Response post(String path,Object b,String token){return req("POST",path,b,token,Map.of("Idempotency-Key",key()));}
 String services(){return "/merchant/stores/"+store+"/booking-services";}
 String create(){var r=post(services(),Map.of("title","TEST wash","kind","GROOMING"),merchant);assertEquals(200,r.status(),r.body().toString());return r.id();}
 Map<String,Object> interval(int seats){Instant start=clock.instant().plus(Duration.ofDays(2)).truncatedTo(java.time.temporal.ChronoUnit.SECONDS);return Map.of("starts_at",start.toString(),"ends_at",start.plusSeconds(3600).toString(),"capacity",seats);}
 String slot(String service,int seats){var r=post("/merchant/booking-services/"+service+"/slots",interval(seats),merchant);assertEquals(200,r.status(),r.body().toString());return r.id();}
 Response reserve(String slot,String who,String k){return req("POST","/consumer/service-bookings",Map.of("slot_id",slot),who,Map.of("Idempotency-Key",k));}
 Response cancel(String booking,String who,String k,long v){return req("POST","/consumer/service-bookings/"+booking+"/cancel",Map.of(),who,Map.of("Idempotency-Key",k,"If-Match","\""+v+"\""));}
 Response state(String service,String status,long v){return req("PUT","/merchant/booking-services/"+service+"/state",Map.of("status",status),merchant,Map.of("Idempotency-Key",key(),"If-Match","\""+v+"\""));}


 String admin(){UUID p=UUID.randomUUID(),role=UUID.randomUUID();adminSession=UUID.randomUUID();db.update("INSERT INTO identity_principal(id,realm,login_name,password_hash) VALUES (?,'ADMIN',?,'TEST-ONLY')",p,key());db.update("INSERT INTO role(id,scope_type,code,name) VALUES (?,'ADMIN',?,'TEST trade admin')",role,key());db.update("INSERT INTO role_permission SELECT ?,id FROM permission WHERE code='service.terms.review'",role);db.update("INSERT INTO principal_role VALUES (?,?,'ADMIN')",p,role);String token=crypto.token();db.update("INSERT INTO auth_session(id,principal_id,access_token_hash,device_id,expires_at,refresh_expires_at,created_at) VALUES (?,?,?,'TRADE-IT',?,?,?)",adminSession,p,crypto.hash(token),Timestamp.from(clock.instant().plusSeconds(86400)),Timestamp.from(clock.instant().plusSeconds(2592000)),Timestamp.from(clock.instant()));return token;}
 String proof(String action){String token=crypto.token();db.update("INSERT INTO reverify_grant(token_hash,session_id,action,expires_at,created_at) VALUES (?,?,?,?,?)",crypto.hash(token),adminSession,action,Timestamp.from(clock.instant().plusSeconds(300)),Timestamp.from(clock.instant()));return token;}
 Map<String,Object> input(String service,int amount){var b=new LinkedHashMap<String,Object>();b.put("service_id",service);b.put("currency","CNY");b.put("amount_fen",amount);b.put("billing_unit","WHOLE_SLOT");b.put("cancel_cutoff_minutes",60);b.put("consumer_late_cancel","MANUAL_REVIEW");b.put("merchant_cancel","FULL_REFUND");b.put("no_show","MANUAL_REVIEW");b.put("commission_basis_points",333);b.put("settlement_buffer_minutes",120);b.put("evidence_refs",List.of(Map.of("kind","TEST_SCENARIO","reference","TEST_ONLY_B1")));return b;}
 String termsPath(){return "/merchant/stores/"+store+"/service-trade-terms";}
 Response draft(String service,int amount){return post(termsPath(),input(service,amount),merchant);}
 Response review(String id,String who,String proof,String k,long version){return req("POST","/admin/service-trade-terms/"+id+"/review",Map.of("decision","APPROVE_SIMULATION","reason_code","TEST_SCENARIO_REVIEWED"),who,Map.of("X-Reverify-Token",proof,"Idempotency-Key",k,"If-Match","\""+version+"\""));}
 String approved(String service){var d=draft(service,101);assertEquals(200,d.status(),d.body().toString());var r=review(d.id(),admin,proof("service.terms.review"),key(),0);assertEquals(200,r.status(),r.body().toString());return d.id();}
 Response quote(String terms,String slot,String who){return post("/consumer/service-trade-quotes",Map.of("terms_id",terms,"slot_id",slot),who);}
 Response trade(Response quote,String who,String key){return req("POST","/consumer/service-trade-orders",Map.of("quote_id",quote.id(),"accepted_terms_sha256",quote.data().get("terms_sha256").asString()),who,Map.of("Idempotency-Key",key));}
 Response tradeCancel(String id,long v,String who,String key){return req("POST","/consumer/service-trade-orders/"+id+"/cancel",Map.of(),who,Map.of("Idempotency-Key",key,"If-Match","\""+v+"\""));}
 int remaining(String service){return get("/consumer/booking-services/"+service+"/slots",user).data().get(0).get("remaining").asInt();}
 String active(String id){return get("/consumer/service-trade-orders/"+id,user).data().get("order_state").asString();}
 @AfterAll static void samples()throws Exception{Path p=Path.of("target/v313-b1-contract-samples.json");Files.createDirectories(p.getParent());Files.writeString(p,JsonMapper.builder().build().writeValueAsString(SAMPLES));}
 @Test void reviewedTermsQuoteHoldReadAndCancelAreRealDurableButNotPaid(){
  String s=create(),slot=slot(s,1),t=approved(s);var shown=get("/consumer/service-trade-terms/"+t,user);assertEquals(200,shown.status());assertFalse(shown.body().toString().contains("commission"));assertFalse(shown.body().toString().contains("evidence_refs"));assertEquals(shown.data(),get("/consumer/booking-services/"+s+"/trade-terms",user).data());
  var q=quote(t,slot,user);assertEquals(200,q.status(),q.body().toString());assertEquals(1,remaining(s));assertFalse(q.data().get("capacity_held").asBoolean());String k=key();var o=trade(q,user,k);assertEquals(200,o.status(),o.body().toString());assertEquals(o.data(),trade(q,user,k).data());assertEquals(0,remaining(s));assertEquals(101,o.data().get("payable_fen").asInt());assertEquals(0,o.data().get("paid_fen").asInt());assertEquals("AWAITING_PAYMENT",active(o.id()));assertEquals(0,db.queryForObject("SELECT count(*) FROM payments",Integer.class));
  assertEquals(1,get("/consumer/service-trade-orders",user).data().size());var merchantView=get("/merchant/stores/"+store+"/service-trade-orders",merchant);assertEquals(1,merchantView.data().size());assertFalse(merchantView.body().toString().contains("user_id"));assertFalse(merchantView.body().toString().contains("policy_snapshot_sha256"));
  assertEquals(200,tradeCancel(o.id(),0,user,key()).status());assertEquals("CANCELLED",active(o.id()));assertEquals(1,remaining(s));assertEquals(409,tradeCancel(o.id(),1,user,key()).status());
 }
 @Test void syntheticRulesRequireEveryExplicitInputAndSeparatePermission(){String s=create();var b=input(s,101);b.remove("commission_basis_points");assertEquals(400,post(termsPath(),b,merchant).status());b=input(s,101);b.put("evidence_refs",List.of(Map.of("kind","CONTRACT","reference","real")));assertEquals(400,post(termsPath(),b,merchant).status());assertEquals(403,post(termsPath(),input(s,101),reader).status());assertEquals(404,post(termsPath(),input(s,101),foreign).status());assertEquals(403,post(termsPath(),input(s,101),user).status());assertEquals(400,draft(s,0).status());var d=draft(s,101);assertEquals(200,d.status());assertEquals(409,get("/consumer/service-trade-terms/"+d.id(),user).status());assertEquals(200,get(termsPath(),merchant).status());assertEquals(200,get("/admin/service-trade-terms?limit=1",admin).status());}
 @Test void reviewRequiresActionBoundOneTimeProofAndAuditFailureRollsBack(){String s=create(),t=draft(s,101).id();assertEquals(403,review(t,admin,"missing",key(),0).status());assertEquals(403,review(t,admin,proof("nearby.moderate"),key(),0).status());String token=proof("service.terms.review"),k=key();db.execute("CREATE FUNCTION test_trade_audit_fail() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='service.terms.review' THEN RAISE EXCEPTION 'TEST audit fail'; END IF; RETURN NEW; END $$");db.execute("CREATE TRIGGER test_trade_audit_fail BEFORE INSERT ON audit_event FOR EACH ROW EXECUTE FUNCTION test_trade_audit_fail()");try{assertEquals(503,review(t,admin,token,k,0).status());}finally{db.execute("DROP TRIGGER test_trade_audit_fail ON audit_event");db.execute("DROP FUNCTION test_trade_audit_fail()");}assertNull(db.queryForObject("SELECT used_at FROM reverify_grant WHERE token_hash=?",Timestamp.class,crypto.hash(token)));assertEquals(200,review(t,admin,token,k,0).status());assertEquals(200,review(t,admin,token,k,0).status());assertEquals(403,review(draft(s,102).id(),admin,token,key(),0).status());}
 @Test void newTermsRetireOldQuotesAndOldSnapshotsAreImmutable(){String s=create(),sl=slot(s,2),old=approved(s);var q=quote(old,sl,user);var o=trade(q,user,key());assertEquals(200,o.status());var q2=quote(old,sl,other);String fresh=draft(s,999).id();assertEquals(200,review(fresh,admin,proof("service.terms.review"),key(),0).status());assertEquals(409,trade(q2,other,key()).status());assertEquals(101,get("/consumer/service-trade-orders/"+o.id(),user).data().get("payable_fen").asInt());assertEquals(999,get("/consumer/booking-services/"+s+"/trade-terms",user).data().get("amount_fen").asInt());for(String sql:List.of("UPDATE service_trade_terms SET snapshot='{}'","UPDATE service_trade_quotes SET payable_fen=1","UPDATE service_trade_orders SET payable_fen=1","DELETE FROM service_trade_orders","TRUNCATE service_trade_orders","TRUNCATE service_trade_quotes","TRUNCATE service_trade_terms"))assertThrows(org.springframework.dao.DataAccessException.class,()->db.execute(sql));}
 @Test void quoteOwnershipTermsConsentVersionsAndServerPriceAreEnforced(){String s=create(),sl=slot(s,2),t=approved(s);var q=quote(t,sl,user);assertEquals(404,trade(q,other,key()).status());assertEquals(400,post("/consumer/service-trade-orders",Map.of("quote_id",q.id(),"accepted_terms_sha256",q.data().get("terms_sha256").asString(),"payable_fen",1),user).status());assertEquals(409,post("/consumer/service-trade-orders",Map.of("quote_id",q.id(),"accepted_terms_sha256","a".repeat(64)),user).status());assertEquals(200,state(s,"PAUSED",0).status());assertEquals(409,trade(q,user,key()).status());assertEquals(200,state(s,"ACTIVE",1).status());assertEquals(409,trade(q,user,key()).status());assertEquals(400,get("/consumer/service-trade-orders?limit=101",user).status());assertEquals(401,get("/consumer/service-trade-orders",null).status());assertEquals(403,get("/consumer/service-trade-orders",merchant).status());}
 @Test void mixedOldAndNewCapacitySerializesBothDirections()throws Exception{String s=create(),sl=slot(s,1),t=approved(s);var q=quote(t,sl,user);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var latch=new CountDownLatch(1);var a=pool.submit(()->{latch.await();return trade(q,user,key());});var b=pool.submit(()->{latch.await();return reserve(sl,other,key());});latch.countDown();var statuses=new ArrayList<>(List.of(a.get().status(),b.get().status()));Collections.sort(statuses);assertEquals(List.of(200,409),statuses);}assertEquals(0,remaining(s));}
 @Test void sameKeyConcurrentReserveCreatesOnlyOneHold()throws Exception{String s=create(),sl=slot(s,2),t=approved(s);var q=quote(t,sl,user);String k=key();try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var a=pool.submit(()->trade(q,user,k));var b=pool.submit(()->trade(q,user,k));assertEquals(200,a.get().status());assertEquals(200,b.get().status());}assertEquals(1,remaining(s));assertEquals(409,trade(q,user,key()).status());assertEquals(409,reserve(sl,user,key()).status());}
 @Test void expiredQuoteDoesNotHoldCapacityAndUnstartedHoldExpiresDurably(){String s=create(),sl=slot(s,1),t=approved(s);var q=quote(t,sl,user);time.current=time.current.plusSeconds(301);assertEquals(409,trade(q,user,key()).status());assertEquals(1,remaining(s));var o=trade(quote(t,sl,user),user,key());assertEquals(200,o.status());assertTrue(Instant.parse(o.data().get("hold_expires_at").asString()).isBefore(Instant.parse(o.data().get("starts_at").asString())));time.current=time.current.plusSeconds(601);assertTrue(tradeService.expireBatch()>=1);assertEquals("EXPIRED",active(o.id()));assertEquals(1,remaining(s));assertEquals(0,tradeService.expireBatch());}
 @Test void foreignAndRevokedReadersCannotReplayOrReadTrades(){String s=create(),sl=slot(s,1),t=approved(s);var o=trade(quote(t,sl,user),user,key());assertEquals(404,get("/consumer/service-trade-orders/"+o.id(),other).status());assertEquals(404,tradeCancel(o.id(),0,other,key()).status());assertEquals(404,get("/merchant/stores/"+store+"/service-trade-orders",foreign).status());assertEquals(403,get("/merchant/stores/"+store+"/service-trade-orders",reader).status());db.update("DELETE FROM principal_store_scope WHERE store_id=? AND principal_id IN (SELECT principal_id FROM auth_session WHERE access_token_hash=?)",store,crypto.hash(merchant));assertEquals(404,get(termsPath(),merchant).status());}
 @Test void hiddenStoreCannotIssueOrConsumeQuotesButOwnerCanCloseHold(){String s=create(),sl=slot(s,2),t=approved(s);var q=quote(t,sl,user);var o=trade(q,user,key());var q2=quote(t,sl,other);db.update("UPDATE nearby_store_profile SET publication_status='HIDDEN' WHERE store_id=?",store);assertEquals(404,quote(t,sl,other).status());assertEquals(404,trade(q2,other,key()).status());assertEquals(200,get("/consumer/service-trade-orders/"+o.id(),user).status());assertEquals(200,tradeCancel(o.id(),0,user,key()).status());}
 @Test void oldBookingAndTradeCapacityBothBlockUntilTheirOwnCancellation(){String s=create(),sl=slot(s,1),t=approved(s);var old=reserve(sl,user,key());assertEquals(200,old.status());var q=quote(t,sl,other);assertEquals(409,trade(q,other,key()).status());assertEquals(200,cancel(old.id(),user,key(),0).status());var o=trade(q,other,key());assertEquals(200,o.status());assertEquals(409,reserve(sl,user,key()).status());assertEquals(200,tradeCancel(o.id(),0,other,key()).status());assertEquals(200,reserve(sl,user,key()).status());}
 @Test void holdAndQuoteBoundariesStopAtSlotStart(){String s=create();Instant start=clock.instant().plusSeconds(120).truncatedTo(java.time.temporal.ChronoUnit.SECONDS);var sl=post("/merchant/booking-services/"+s+"/slots",Map.of("starts_at",start.toString(),"ends_at",start.plusSeconds(3600).toString(),"capacity",1),merchant);assertEquals(200,sl.status());String t=approved(s);var q=quote(t,sl.id(),user);assertEquals(start,Instant.parse(q.data().get("expires_at").asString()));var o=trade(q,user,key());assertEquals(start,Instant.parse(o.data().get("hold_expires_at").asString()));time.current=start;assertTrue(tradeService.expireBatch()>=1);assertEquals("EXPIRED",active(o.id()));assertEquals(409,quote(t,sl.id(),other).status());}
 @Test void replayStillChecksStoreScopeAndClientCannotReuseKeyWithChangedPayload(){String s=create(),k=key();var b=input(s,101);var d=req("POST",termsPath(),b,merchant,Map.of("Idempotency-Key",k));assertEquals(200,d.status());assertEquals(409,req("POST",termsPath(),input(s,102),merchant,Map.of("Idempotency-Key",k)).status());db.update("DELETE FROM principal_store_scope WHERE store_id=? AND principal_id IN (SELECT principal_id FROM auth_session WHERE access_token_hash=?)",store,crypto.hash(merchant));assertEquals(404,req("POST",termsPath(),b,merchant,Map.of("Idempotency-Key",k)).status());}
}
